args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Vote_for_Huggett dbr:Romance_in_the_Dark }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate. }
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel. FILTER(lang(?directorLabel) = "en") }
}

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  dbr:Vote_for_Huggett dbo:director ?dir1 .
  dbr:Romance_in_the_Dark dbo:director ?dir2 .
  ?dir1 dbo:birthDate ?bd1 .
  ?dir2 dbo:birthDate ?bd2 .
  FILTER(?bd1 > ?bd2) .
  BIND(dbr:Vote_for_Huggett AS ?film) .
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(lang(?filmLabel) = "en") }
  BIND(?dir1 AS ?director) .
  OPTIONAL { ?director rdfs:label ?directorLabel. FILTER(lang(?directorLabel) = "en") }
  BIND(?bd1 AS ?birthDate) .
}

